package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.TypeDeserializer;
import com.fasterxml.jackson.databind.deser.UnresolvedForwardReference;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.impl.untyped.UntypedObjectDeserializer;
import com.fasterxml.jackson.databind.deser.std.ContainerDeserializerBase;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.ser.std.StdSerializer;
import com.fasterxml.jackson.databind.util.TypeSerializerInfo;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CollectionDeserializer_deserialize_TriageGen2Test {

    private JsonParser p;
    private DeserializationContext ctxt;
    private JavaType collectionType;
    private JavaType contentType;
    private JsonDeserializer<Object> valueDes;
    private TypeDeserializer typeDeser;
    private Collection<Object> result;

    @Before
    public void setUp() {
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        collectionType = mock(JavaType.class);
        contentType = mock(JavaType.class);
        valueDes = mock(JsonDeserializer.class);
        typeDeser = mock(TypeDeserializer.class);
        result = new ArrayList<>();

        when(collectionType.getContentType()).thenReturn(contentType);
        when(contentType.getRawClass()).thenReturn(Object.class);
    }

    @Test
    public void testDeserialize_NonArrayToken() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(false);

        // We need to spy the deserializer to mock handleNonArray since it's protected
        CollectionDeserializer deserializer = spy(new CollectionDeserializer(collectionType, valueDes, typeDeser, null));
        Collection<Object> expectedReturn = new ArrayList<>();
        doReturn(expectedReturn).when(deserializer).handleNonArray(p, ctxt, result);

        Collection<Object> actual = deserializer.deserialize(p, ctxt, result);

        assertEquals(expectedReturn, actual);
        verify(deserializer).handleNonArray(p, ctxt, result);
    }

    @Test
    public void testDeserialize_ArrayWithNullValue() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextToken()).thenReturn(JsonToken.VALUE_NULL, JsonToken.END_ARRAY);
        when(valueDes.getNullValue(ctxt)).thenReturn(null);
        when(valueDes.getObjectIdReader()).thenReturn(null);

        CollectionDeserializer deserializer = new CollectionDeserializer(collectionType, valueDes, null, null);
        Collection<Object> actual = deserializer.deserialize(p, ctxt, result);

        assertEquals(1, actual.size());
        assertNull(actual.get(0));
        verify(p).setCurrentValue(result);
    }

    @Test
    public void testDeserialize_ArrayWithNormalValues_NoTypeDeserializer() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextToken()).thenReturn(JsonToken.START_ARRAY, JsonToken.VALUE_STRING, JsonToken.END_ARRAY);
        when(valueDes.getObjectIdReader()).thenReturn(null);
        when(valueDes.deserialize(p, ctxt)).thenReturn("testValue");

        CollectionDeserializer deserializer = new CollectionDeserializer(collectionType, valueDes, null, null);
        Collection<Object> actual = deserializer.deserialize(p, ctxt, result);

        assertEquals(1, actual.size());
        assertEquals("testValue", actual.get(0));
    }

    @Test
    public void testDeserialize_ArrayWithNormalValues_WithTypeDeserializer() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextToken()).thenReturn(JsonToken.START_ARRAY, JsonToken.VALUE_STRING, JsonToken.END_ARRAY);
        when(valueDes.getObjectIdReader()).thenReturn(null);
        when(valueDes.deserializeWithType(p, ctxt, typeDeser)).thenReturn("typedValue");

        CollectionDeserializer deserializer = new CollectionDeserializer(collectionType, valueDes, typeDeser, null);
        Collection<Object> actual = deserializer.deserialize(p, ctxt, result);

        assertEquals(1, actual.size());
        assertEquals("typedValue", actual.get(0));
    }

    @Test
    public void testDeserialize_UnresolvedForwardReference_NoIdentityInfo() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextToken()).thenReturn(JsonToken.START_ARRAY, JsonToken.VALUE_STRING, JsonToken.END_ARRAY);
        when(valueDes.getObjectIdReader()).thenReturn(null);

        // Simulate UnresolvedForwardReference
        UnresolvedForwardReference ref = new UnresolvedForwardReference("id", null);
        when(valueDes.deserialize(p, ctxt)).thenThrow(ref);

        CollectionDeserializer deserializer = new CollectionDeserializer(collectionType, valueDes, null, null);

        try {
            deserializer.deserialize(p, ctxt, result);
            fail("Should have thrown JsonMappingException");
        } catch (JsonMappingException e) {
            assertTrue(e.getMessage().contains("Unresolved forward reference but no identity info"));
        }
    }

    @Test
    public void testDeserialize_ExceptionWrapping_WithFeatureEnabled() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextToken()).thenReturn(JsonToken.START_ARRAY, JsonToken.VALUE_STRING, JsonToken.END_ARRAY);
        when(valueDes.getObjectIdReader()).thenReturn(null);

        RuntimeException cause = new RuntimeException("error");
        when(valueDes.deserialize(p, ctxt)).thenThrow(cause);
        when(ctxt.isEnabled(DeserializationFeature.WRAP_EXCEPTIONS)).thenReturn(true);

        CollectionDeserializer deserializer = new CollectionDeserializer(collectionType, valueDes, null, null);

        try {
            deserializer.deserialize(p, ctxt, result);
            fail("Should have thrown JsonMappingException");
        } catch (JsonMappingException e) {
            assertEquals(cause, e.getCause());
        }
    }

    @Test
    public void testDeserialize_ExceptionWrapping_WithoutFeature_RethrowRuntimeException() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextToken()).thenReturn(JsonToken.START_ARRAY, JsonToken.VALUE_STRING, JsonToken.END_ARRAY);
        when(valueDes.getObjectIdReader()).thenReturn(null);

        RuntimeException cause = new RuntimeException("error");
        when(valueDes.deserialize(p, ctxt)).thenThrow(cause);
        when(ctxt.isEnabled(DeserializationFeature.WRAP_EXCEPTIONS)).thenReturn(false);

        CollectionDeserializer deserializer = new CollectionDeserializer(collectionType, valueDes, null, null);

        // Should rethrow the RuntimeException directly
        try {
            deserializer.deserialize(p, ctxt, result);
            fail("Should have thrown RuntimeException");
        } catch (RuntimeException e) {
            assertEquals(cause, e);
        }
    }

    @Test
    public void testDeserialize_ExceptionWrapping_WithoutFeature_WrapOtherException() throws IOException {
        when(p.isExpectedStartArrayToken()).thenReturn(true);
        when(p.nextToken()).thenReturn(JsonToken.START_ARRAY, JsonToken.VALUE_STRING, JsonToken.END_ARRAY);
        when(valueDes.getObjectIdReader()).thenReturn(null);

        IOException cause = new IOException("error");
        when(valueDes.deserialize(p, ctxt)).thenThrow(cause);
        when(ctxt.isEnabled(DeserializationFeature.WRAP_EXCEPTIONS)).thenReturn(false);

        CollectionDeserializer deserializer = new CollectionDeserializer(collectionType, valueDes, null, null);

        try {
            deserializer.deserialize(p, ctxt, result);
            fail("Should have thrown JsonMappingException");
        } catch (JsonMappingException e) {
            assertEquals(cause, e.getCause());
        }
    }
}
